export interface Frontmatter {
  title: string;
  date?: string;
  tags?: string[];
  draft?: boolean;
  layout?: string;
  [key: string]: unknown;
}

export interface Page {
  frontmatter: Frontmatter;
  content: string;
  html: string;
  slug: string;
  sourcePath: string;
  outputPath: string;
}

export interface TagIndexEntry {
  tag: string;
  pages: Page[];
}

export interface SiteConfig {
  title: string;
  description: string;
  url: string;
  author?: string;
  language?: string;
  postsPerPage?: number;
}

import fs from "fs";
import path from "path";
import fm from "front-matter";
import { Marked } from "marked";
import { markedHighlight } from "marked-highlight";
import hljs from "highlight.js";
import type { Frontmatter, Page } from "../types";

const marked = new Marked(
  markedHighlight({
    langPrefix: "hljs language-",
    highlight(code: string, lang: string) {
      if (lang && hljs.getLanguage(lang)) {
        return hljs.highlight(code, { language: lang }).value;
      }
      return code;
    },
  })
);

export function parseFrontmatter(raw: string): {
  frontmatter: Frontmatter;
  body: string;
} {
  const parsed = fm<Frontmatter>(raw);
  return {
    frontmatter: parsed.attributes,
    body: parsed.body,
  };
}

export function markdownToHtml(markdown: string): string {
  return marked.parse(markdown) as string;
}

export function parseMarkdownFile(
  filePath: string,
  sourceDir: string,
  outputDir: string
): Page {
  const raw = fs.readFileSync(filePath, "utf-8");
  const { frontmatter, body } = parseFrontmatter(raw);
  const html = markdownToHtml(body);

  const relativePath = path.relative(sourceDir, filePath);
  const parsed = path.parse(relativePath);
  const slug = path.join(parsed.dir, parsed.name).replace(/\\/g, "/");
  const outputPath = path.join(
    outputDir,
    parsed.dir,
    `${parsed.name}.html`
  );

  return {
    frontmatter,
    content: body,
    html,
    slug: slug || "index",
    sourcePath: filePath,
    outputPath,
  };
}

export function loadPages(
  sourceDir: string,
  outputDir: string
): { pages: Page[]; drafts: Page[] } {
  const allPages: Page[] = [];
  const drafts: Page[] = [];

  function walk(dir: string) {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      const fullPath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(fullPath);
      } else if (entry.name.endsWith(".md")) {
        const page = parseMarkdownFile(fullPath, sourceDir, outputDir);
        if (page.frontmatter.draft) {
          drafts.push(page);
        } else {
          allPages.push(page);
        }
      }
    }
  }

  walk(sourceDir);

  allPages.sort((a, b) => {
    const dateA = a.frontmatter.date
      ? new Date(a.frontmatter.date).getTime()
      : 0;
    const dateB = b.frontmatter.date
      ? new Date(b.frontmatter.date).getTime()
      : 0;
    return dateB - dateA;
  });

  return { pages: allPages, drafts };
}

import fs from "fs";
import path from "path";
import Handlebars from "handlebars";
import type { Page, SiteConfig, TagIndexEntry } from "../types";

export class TemplateEngine {
  private partialsDir: string;
  private layoutDir: string;
  private compiledPartials: Map<string, HandlebarsTemplateDelegate> =
    new Map();
  private compiledLayouts: Map<string, HandlebarsTemplateDelegate> =
    new Map();

  constructor(templatesDir: string) {
    this.partialsDir = path.join(templatesDir, "partials");
    this.layoutDir = path.join(templatesDir, "layouts");
    this.registerPartials();
    this.registerHelpers();
  }

  private registerHelpers() {
    Handlebars.registerHelper("formatDate", (date: string) => {
      if (!date) return "";
      return new Date(date).toLocaleDateString("en-US", {
        year: "numeric",
        month: "long",
        day: "numeric",
      });
    });

    Handlebars.registerHelper("isoDate", (date: string) => {
      if (!date) return "";
      return new Date(date).toISOString();
    });

    Handlebars.registerHelper("excerpt", (html: string, words: number) => {
      const text = html.replace(/<[^>]*>/g, "");
      const trimmed = text.split(/\s+/).slice(0, words).join(" ");
      return trimmed + (text.split(/\s+/).length > words ? "..." : "");
    });

    Handlebars.registerHelper("eq", (a: unknown, b: unknown) => a === b);
  }

  private registerPartials() {
    if (!fs.existsSync(this.partialsDir)) return;
    const files = fs.readdirSync(this.partialsDir);
    for (const file of files) {
      if (file.endsWith(".hbs") || file.endsWith(".html")) {
        const name = path.parse(file).name;
        const content = fs.readFileSync(
          path.join(this.partialsDir, file),
          "utf-8"
        );
        Handlebars.registerPartial(name, content);
      }
    }
  }

  private compileTemplate(templatePath: string): HandlebarsTemplateDelegate {
    const content = fs.readFileSync(templatePath, "utf-8");
    return Handlebars.compile(content);
  }

  private getLayout(layoutName: string | undefined): HandlebarsTemplateDelegate {
    const name = layoutName || "default";
    if (this.compiledLayouts.has(name)) {
      return this.compiledLayouts.get(name)!;
    }
    // Try layouts dir, then root
    const candidates = [
      path.join(this.layoutDir, `${name}.hbs`),
      path.join(this.layoutDir, `${name}.html`),
    ];
    for (const candidate of candidates) {
      if (fs.existsSync(candidate)) {
        const compiled = this.compileTemplate(candidate);
        this.compiledLayouts.set(name, compiled);
        return compiled;
      }
    }
    // Fallback: simple wrapper layout
    const fallback = Handlebars.compile("{{{body}}}");
    this.compiledLayouts.set(name, fallback);
    return fallback;
  }

  renderPage(
    page: Page,
    allPages: Page[],
    site: SiteConfig
  ): string {
    const layout = this.getLayout(page.frontmatter.layout);
    return layout({
      page,
      pages: allPages,
      site,
    });
  }

  renderIndex(
    pages: Page[],
    site: SiteConfig,
    templateName: string = "index"
  ): string {
    const candidates = [
      path.join(this.layoutDir, `${templateName}.hbs`),
      path.join(this.layoutDir, `${templateName}.html`),
    ];

    for (const candidate of candidates) {
      if (fs.existsSync(candidate)) {
        const compiled = this.compileTemplate(candidate);
        return compiled({ pages, site });
      }
    }

    // Default index template
    const defaultIndex = Handlebars.compile(`<!DOCTYPE html>
<html lang="{{site.language}}">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>{{site.title}}</title>
</head>
<body>
  <h1>{{site.title}}</h1>
  {{#each pages}}
  <article>
    <h2><a href="/{{slug}}.html">{{frontmatter.title}}</a></h2>
    {{#if frontmatter.date}}<time>{{frontmatter.date}}</time>{{/if}}
    <div>{{{html}}}</div>
  </article>
  {{/each}}
</body>
</html>`);
    return defaultIndex({ pages, site });
  }

  renderTagPage(
    tagEntry: TagIndexEntry,
    site: SiteConfig
  ): string {
    const candidates = [
      path.join(this.layoutDir, "tag.hbs"),
      path.join(this.layoutDir, "tag.html"),
    ];

    for (const candidate of candidates) {
      if (fs.existsSync(candidate)) {
        const compiled = this.compileTemplate(candidate);
        return compiled({ tag: tagEntry.tag, pages: tagEntry.pages, site });
      }
    }

    const defaultTag = Handlebars.compile(`<!DOCTYPE html>
<html lang="{{site.language}}">
<head>
  <meta charset="UTF-8">
  <title>Tag: {{tag}} - {{site.title}}</title>
</head>
<body>
  <h1>Posts tagged "{{tag}}"</h1>
  {{#each pages}}
  <article>
    <h2><a href="/{{slug}}.html">{{frontmatter.title}}</a></h2>
    {{#if frontmatter.date}}<time>{{frontmatter.date}}</time>{{/if}}
  </article>
  {{/each}}
</body>
</html>`);
    return defaultTag({ tag: tagEntry.tag, pages: tagEntry.pages, site });
  }
}

import path from "path";
import type { Page, TagIndexEntry, SiteConfig } from "../types";

export function buildTagIndex(pages: Page[]): TagIndexEntry[] {
  const tagMap = new Map<string, Page[]>();

  for (const page of pages) {
    const tags = page.frontmatter.tags || [];
    for (const tag of tags) {
      const normalized = tag.trim().toLowerCase();
      if (!tagMap.has(normalized)) {
        tagMap.set(normalized, []);
      }
      tagMap.get(normalized)!.push(page);
    }
  }

  const entries: TagIndexEntry[] = [];
  for (const [tag, taggedPages] of tagMap) {
    entries.push({ tag, pages: taggedPages });
  }

  return entries.sort((a, b) => a.tag.localeCompare(b.tag));
}

export function computePageOutputPath(page: Page): string {
  return path.normalize(page.outputPath);
}

export function resolveAssetPath(
  outputDir: string,
  relativePath: string
): string {
  return path.join(outputDir, relativePath);
}

export { buildRssFeed } from "./rss";

import RSS from "rss";
import type { Page, SiteConfig } from "../types";

export function buildRssFeed(
  pages: Page[],
  site: SiteConfig
): string {
  const feed = new RSS({
    title: site.title,
    description: site.description,
    feed_url: `${site.url}/feed.xml`,
    site_url: site.url,
    language: site.language || "en",
  });

  for (const page of pages) {
    if (page.frontmatter.draft) continue;
    feed.item({
      title: page.frontmatter.title,
      description: page.html,
      url: `${site.url}/${page.slug}.html`,
      date: page.frontmatter.date || new Date().toISOString(),
      categories: page.frontmatter.tags || [],
    });
  }

  return feed.xml({ indent: true });
}

import fs from "fs";
import path from "path";
import { loadPages } from "../parsers/markdown";
import { TemplateEngine } from "../renderers/template";
import { buildTagIndex } from "../generators/index";
import { buildRssFeed } from "../generators/rss";
import type { SiteConfig } from "../types";

export interface BuildOptions {
  sourceDir: string;
  outputDir: string;
  templatesDir: string;
  site: SiteConfig;
  verbose?: boolean;
}

export function build(options: BuildOptions): number {
  const { sourceDir, outputDir, templatesDir, site, verbose } = options;

  if (!fs.existsSync(sourceDir)) {
    console.error(`Source directory not found: ${sourceDir}`);
    return 1;
  }

  if (verbose) console.log(`Loading pages from ${sourceDir}...`);
  const { pages } = loadPages(sourceDir, outputDir);
  if (verbose) console.log(`Found ${pages.length} pages.`);

  const engine = new TemplateEngine(templatesDir);

  if (verbose) console.log(`Writing output to ${outputDir}...`);
  fs.rmSync(outputDir, { recursive: true, force: true });
  fs.mkdirSync(outputDir, { recursive: true });

  for (const page of pages) {
    const html = engine.renderPage(page, pages, site);
    fs.mkdirSync(path.dirname(page.outputPath), { recursive: true });
    fs.writeFileSync(page.outputPath, html, "utf-8");
    if (verbose) console.log(`  ${page.slug}.html`);
  }

  const indexHtml = engine.renderIndex(pages, site);
  fs.writeFileSync(path.join(outputDir, "index.html"), indexHtml, "utf-8");
  if (verbose) console.log("  index.html");

  const tagEntries = buildTagIndex(pages);
  const tagsDir = path.join(outputDir, "tags");
  fs.mkdirSync(tagsDir, { recursive: true });
  for (const entry of tagEntries) {
    const tagHtml = engine.renderTagPage(entry, site);
    const tagOutputPath = path.join(tagsDir, `${entry.tag}.html`);
    fs.writeFileSync(tagOutputPath, tagHtml, "utf-8");
    if (verbose) console.log(`  tags/${entry.tag}.html`);
  }

  const rssXml = buildRssFeed(pages, site);
  fs.writeFileSync(path.join(outputDir, "feed.xml"), rssXml, "utf-8");
  if (verbose) console.log("  feed.xml");

  if (verbose) console.log("Site built successfully.");
  return 0;
}

import http from "http";
import fs from "fs";
import path from "path";
import { WebSocketServer, WebSocket } from "ws";
import chokidar from "chokidar";
import { build } from "../generators/build";
import type { SiteConfig } from "../types";

const LIVE_RELOAD_SCRIPT = `
<script>
(function() {
  var protocol = location.protocol === "https:" ? "wss:" : "ws:";
  var ws = new WebSocket(protocol + "//" + location.host + "/__livereload");
  ws.onmessage = function(msg) {
    if (msg.data === "reload") {
      console.log("[staticsmith] Reloading...");
      location.reload();
    }
  };
  ws.onclose = function() {
    console.log("[staticsmith] Live reload disconnected, attempting reconnect...");
    setTimeout(function() {
      location.reload();
    }, 1500);
  };
})();
</script>
`;

export interface ServeOptions {
  sourceDir: string;
  outputDir: string;
  templatesDir: string;
  site: SiteConfig;
  port: number;
  verbose?: boolean;
}

export function serve(options: ServeOptions): http.Server {
  const { sourceDir, outputDir, templatesDir, site, port } = options;

  const result = build({ sourceDir, outputDir, templatesDir, site });
  if (result !== 0) {
    process.exit(1);
  }

  const server = http.createServer((req, res) => {
    let urlPath = (req.url || "/").split("?")[0];
    if (urlPath === "/") urlPath = "/index.html";

    const filePath = path.join(outputDir, urlPath);

    const ext = path.extname(filePath).toLowerCase();
    const mimeTypes: Record<string, string> = {
      ".html": "text/html",
      ".css": "text/css",
      ".js": "application/javascript",
      ".json": "application/json",
      ".xml": "application/xml",
      ".png": "image/png",
      ".jpg": "image/jpeg",
      ".svg": "image/svg+xml",
      ".ico": "image/x-icon",
    };
    const mimeType = mimeTypes[ext] || "application/octet-stream";

    if (!fs.existsSync(filePath)) {
      res.writeHead(404);
      res.end("Not found");
      return;
    }

    let content = fs.readFileSync(filePath);

    if (ext === ".html") {
      content = Buffer.concat([
        content,
        Buffer.from(LIVE_RELOAD_SCRIPT),
      ]);
    }

    res.writeHead(200, { "Content-Type": mimeType });
    res.end(content);
  });

  const wss = new WebSocketServer({ server });

  wss.on("connection", (ws: WebSocket) => {
    ws.send("connected");
  });

  const watcher = chokidar.watch(
    [sourceDir, templatesDir],
    {
      ignoreInitial: true,
    }
  );

  watcher.on("all", () => {
    console.log("[staticsmith] Changes detected, rebuilding...");
    build({ sourceDir, outputDir, templatesDir, site, verbose: options.verbose });
    for (const client of wss.clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send("reload");
      }
    }
    console.log("[staticsmith] Rebuild complete.");
  });

  server.listen(port, () => {
    console.log(`[staticsmith] Dev server running at http://localhost:${port}`);
    console.log("[staticsmith] Watching for changes...");
  });

  process.on("SIGINT", () => {
    watcher.close();
    wss.close();
    server.close();
    process.exit(0);
  });

  return server;
}

import fs from "fs";
import path from "path";

export function resolveConfigPath(customPath?: string): string {
  if (customPath) {
    if (fs.existsSync(customPath)) return customPath;
    throw new Error(`Config file not found: ${customPath}`);
  }
  const candidates = [
    path.join(process.cwd(), "staticsmith.json"),
    path.join(process.cwd(), "staticsmith.config.json"),
  ];
  for (const candidate of candidates) {
    if (fs.existsSync(candidate)) return candidate;
  }
  throw new Error(
    "No config file found. Create staticsmith.json in your project root."
  );
}

export function loadConfig(configPath?: string): {
  site: {
    title: string;
    description: string;
    url: string;
    author?: string;
    language?: string;
  };
  sourceDir?: string;
  outputDir?: string;
  templatesDir?: string;
} {
  const resolved = resolveConfigPath(configPath);
  return JSON.parse(fs.readFileSync(resolved, "utf-8"));
}

#!/usr/bin/env node
import { Command } from "commander";
import path from "path";
import { build } from "./generators/build";
import { serve } from "./server/dev";
import { loadConfig } from "./commands/config";
import type { SiteConfig } from "./types";

const program = new Command();

program
  .name("staticsmith")
  .description("Static site generator from Markdown + Handlebars")
  .version("1.0.0");

program
  .command("build")
  .description("Build the static site")
  .option("-s, --source <dir>", "Source directory of Markdown files")
  .option("-o, --output <dir>", "Output directory for generated HTML")
  .option("-t, --templates <dir>", "Templates directory (Handlebars)")
  .option(
    "-c, --config <path>",
    "Path to staticsmith.json config file"
  )
  .option("-v, --verbose", "Verbose output")
  .action((opts) => {
    const config = loadConfig(opts.config);
    const sourceDir = path.resolve(
      opts.source || config.sourceDir || "content"
    );
    const outputDir = path.resolve(
      opts.output || config.outputDir || "public"
    );
    const templatesDir = path.resolve(
      opts.templates || config.templatesDir || "templates"
    );
    const site: SiteConfig = {
      title: config.site.title,
      description: config.site.description,
      url: config.site.url,
      author: config.site.author,
      language: config.site.language || "en",
    };

    const result = build({
      sourceDir,
      outputDir,
      templatesDir,
      site,
      verbose: opts.verbose,
    });
    process.exit(result);
  });

program
  .command("serve")
  .description("Start dev server with live reload")
  .option("-s, --source <dir>", "Source directory of Markdown files")
  .option("-o, --output <dir>", "Output directory for generated HTML")
  .option("-t, --templates <dir>", "Templates directory (Handlebars)")
  .option("-c, --config <path>", "Path to staticsmith.json config file")
  .option("-p, --port <number>", "Dev server port", "3000")
  .option("-v, --verbose", "Verbose output")
  .action((opts) => {
    const config = loadConfig(opts.config);
    const sourceDir = path.resolve(
      opts.source || config.sourceDir || "content"
    );
    const outputDir = path.resolve(
      opts.output || config.outputDir || "public"
    );
    const templatesDir = path.resolve(
      opts.templates || config.templatesDir || "templates"
    );
    const site: SiteConfig = {
      title: config.site.title,
      description: config.site.description,
      url: config.site.url,
      author: config.site.author,
      language: config.site.language || "en",
    };

    serve({
      sourceDir,
      outputDir,
      templatesDir,
      site,
      port: parseInt(opts.port, 10),
      verbose: opts.verbose,
    });
  });

program.parse(process.argv);
